package com.codearena.messaging; import org.springframework.amqp.core.*; import org.springframework.context.annotation.*;
@Configuration public class MessagingConfig { @Bean DirectExchange submissionExchange(){return new DirectExchange("submission.exchange");} @Bean Queue submissionQueue(){return QueueBuilder.durable("submission.execute").deadLetterExchange("submission.dlx").build();} @Bean Binding submissionBinding(){return BindingBuilder.bind(submissionQueue()).to(submissionExchange()).with("submission.created");} @Bean FanoutExchange submissionDlx(){return new FanoutExchange("submission.dlx");} @Bean Queue submissionDlq(){return QueueBuilder.durable("submission.dead").build();} @Bean Binding deadBinding(){return BindingBuilder.bind(submissionDlq()).to(submissionDlx());} }
